import itertools
from z3 import *

n = 17
min_edges = 26
max_color = 3

# Edge variables: e[i][j] for i&lt;j
edge_vars = {}
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = Bool(f'e_{i}_{j}')

# Color variables: c[i] in {0,1,2}
color_vars = [Int(f'c_{i}') for i in range(n)]

s = Solver()

# Color domains
for i in range(n):
    s.add(color_vars[i] &gt;= 0, color_vars[i] &lt; max_color)

# Edge implies different colors
for i in range(n):
    for j in range(i+1, n):
        s.add(Implies(edge_vars[(i,j)], color_vars[i] != color_vars[j]))

# At least min_edges edges
s.add(PbGe([(edge_vars[(i,j)], 1) for i in range(n) for j in range(i+1, n)], min_edges))

# Girth &gt;= 7: for every subset S of size k in {3,4,5,6}, at most k-1 edges inside S
for k in range(3, 7):
    for S in itertools.combinations(range(n), k):
        edges_in_S = []
        for idx_i in range(k):
            for idx_j in range(idx_i+1, k):
                i = S[idx_i]
                j = S[idx_j]
                edges_in_S.append((edge_vars[(i,j)], 1))
        if edges_in_S:
            s.add(PbLe(edges_in_S, k-1))

print("Number of assertions:", len(s.assertions()))
print("Solving...")
res = s.check()
print("Result:", res)
if res == sat:
    m = s.model()
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if m.evaluate(edge_vars[(i,j)], model_completion=True):
                edges.append((i,j))
    colors = [m.evaluate(color_vars[i]).as_long() for i in range(n)]
    print("Edges:", edges)
    print("Number of edges:", len(edges))
    print("Colors:", colors)
else:
    print("UNSAT")

